namespace Clc.Polaris.Api.UnitTests.SerializationAndModels.Json.Deserialization { [TestClass][UnitTest] public sealed class JobsPurchaseOrdersResultGetResultTests { [TestMethod] public void RoundTripsDocumentedShape() { var json = """{"PAPIErrorCode":0,"ExternalID":"e","PONumber":"po","PurchaseOrderID":5,"LineItems":[{"ExternalID":"l","Segments":[{"SegmentID":7,"Copies":2}]}],"LineItemErrors":[{"LineItemNumber":1,"SegmentErrors":[{"SegmentNumber":2,"ErrorMessage":"seg"}]}],"ItemRecordCreateErrors":[{"ExternalID":"i","ErrorMessage":"item"}]}"""; var r = System.Text.Json.JsonSerializer.Deserialize<JobsPurchaseOrdersResultGetResult>(json)!; Assert.AreEqual(5, r.PurchaseOrderID); Assert.AreEqual(7, r.LineItems![0].Segments![0].SegmentID); Assert.AreEqual("seg", r.LineItemErrors![0].SegmentErrors![0].ErrorMessage); Assert.AreEqual("item", r.ItemRecordCreateErrors![0].ErrorMessage); } } }
